          transition: left 0.5s ease;
        }

        .idea-card:hover::before {
          left: 100%;
        }

        .task-item {
          background: linear-gradient(135deg, rgba(255, 255, 255, 0.08), rgba(255, 255, 255, 0.04));
          border: 1px solid rgba(255, 255, 255, 0.1);
          border-radius: 12px;
          padding: 14px 18px;
          margin: 8px 0;
