          transition: transform 0.2s ease;
        }

        .task-item:hover::after {
          transform: scaleY(1);
        }

        .header-button {
          background: linear-gradient(135deg, rgba(255, 255, 255, 0.1), rgba(255, 255, 255, 0.05));
          border: 1px solid rgba(255, 255, 255, 0.1);
