          <span>
            {filteredIdeas.length} fikir bulundu
            {searchTerm && ` "${searchTerm}" için`}
            {statusFilter !== 'all' && ` • ${statusFilter}`}
            {priorityFilter !== 'all' && ` • ${priorityFilter} öncelik`}
            {categoryFilter !== 'all' && ` • ${categoryFilter}`}
